export const TEMPLATES: Readonly<Record<string, string>> = {
  last_step: "-- the masked cells of the **last** time step in the slab, for the map layer.\n--   {{expr}}  the value expression over the slab alias `s` (e.g. s.\"CRW_SST\", or\n--             (s.\"analysed_sst\" - 273.15) to convert Kelvin to Celsius)\n--   {{slab}}  the registered griddap file (parquet) or view\n--   {{mask}}  the mask table: latitude, longitude, weight (0,1]\n-- one row per cell: the mask's own latitude/longitude (so the squares land on the dataset grid), the\n-- area weight and the value. cells with no data on that step are kept with a NULL value, so the map\n-- draws the hole instead of moving the neighbouring squares. the join is the same exact equality on\n-- ROUND(x, 3) as stats_daily.sql (float32 axis vs float64 mask).\nWITH joined AS (\n  SELECT\n    s.\"time\"     AS time,\n    m.latitude   AS latitude,\n    m.longitude  AS longitude,\n    m.weight     AS weight,\n    {{expr}}     AS value\n  FROM {{slab}} s\n  JOIN {{mask}} m\n    ON  ROUND(s.latitude::DOUBLE,  3) = ROUND(m.latitude::DOUBLE,  3)\n    AND ROUND(s.longitude::DOUBLE, 3) = ROUND(m.longitude::DOUBLE, 3)\n)\nSELECT\n  -- utc day; via epoch_ms because duckdb-wasm ships without icu, so TIMESTAMPTZ::DATE is unimplemented there\n  make_timestamp(epoch_ms(time) * 1000)::DATE AS date,\n  latitude,\n  longitude,\n  weight,\n  value\nFROM joined\nWHERE time = (SELECT max(time) FROM joined)\nORDER BY latitude, longitude\n",
  points_tabledap: "-- one row per masked sampling station, for the map layer of a tabledap run.\n--   {{expr}}  the value expression over the slab alias `s`\n--   {{slab}}  the registered tabledap file (parquet) or view\n--   {{mask}}  the station table: latitude, longitude\n-- a tabledap window holds many casts at the same position and many depths per cast, so the map\n-- shows each **station**: its mean value over the window, the number of measurements behind it and\n-- the last time it was sampled.\nSELECT\n  m.latitude                                             AS latitude,\n  m.longitude                                            AS longitude,\n  1.0                                                    AS weight,\n  avg({{expr}})                                          AS value,\n  count({{expr}})                                        AS n,\n  make_timestamp(epoch_ms(max(s.\"time\")) * 1000)::DATE   AS date\nFROM {{slab}} s\nJOIN {{mask}} m\n  ON  ROUND(s.latitude::DOUBLE,  5) = ROUND(m.latitude::DOUBLE,  5)\n  AND ROUND(s.longitude::DOUBLE, 5) = ROUND(m.longitude::DOUBLE, 5)\nWHERE {{expr}} IS NOT NULL\nGROUP BY 1, 2\nORDER BY 1, 2\n",
  stats_categorical: "-- per date x class composition for one place from a categorical ERDDAP griddap slab (seascapeR's\n-- sum_ss_grds_to_ts(): how much of the place is in each class on each date).\n--   {{expr}}  the class expression over the slab alias `s` (e.g. s.\"CLASS\"); cast to BIGINT here\n--   {{slab}}  the registered griddap file (parquet) or view\n--   {{mask}}  the mask table: latitude, longitude, weight (0,1]\n-- `fraction` is area-weighted (partial boundary cells count for their overlap) and sums to exactly 1\n-- over the classes of a date; `percent_cells` is the unweighted cell count share.\n-- the join is the same exact equality on ROUND(x, 3) as stats_daily.sql (float32 axis vs float64 mask).\nWITH cells AS (\n  SELECT\n    -- utc day; via epoch_ms because duckdb-wasm ships without icu, so TIMESTAMPTZ::DATE is unimplemented there\n    make_timestamp(epoch_ms(s.\"time\") * 1000)::DATE AS date,\n    CAST({{expr}} AS BIGINT)                        AS class,\n    m.weight                                        AS weight\n  FROM {{slab}} s\n  JOIN {{mask}} m\n    ON  ROUND(s.latitude::DOUBLE,  3) = ROUND(m.latitude::DOUBLE,  3)\n    AND ROUND(s.longitude::DOUBLE, 3) = ROUND(m.longitude::DOUBLE, 3)\n  WHERE {{expr}} IS NOT NULL\n),\ntotals AS (\n  SELECT date, count(*) AS n_total, sum(weight) AS weight_total\n  FROM cells\n  GROUP BY 1\n)\nSELECT\n  c.date                                    AS date,\n  c.class                                   AS class,\n  count(*)                                  AS n,\n  sum(c.weight)                             AS weight,\n  sum(c.weight) / any_value(t.weight_total) AS fraction,\n  100.0 * count(*) / any_value(t.n_total)   AS percent_cells\nFROM cells c\nJOIN totals t USING (date)\nGROUP BY c.date, c.class\nORDER BY 1, 2\n",
  stats_daily: "-- daily key statistics for one place from an ERDDAP griddap slab.\n--   {{expr}}  the value expression over the slab alias `s` (e.g. s.\"CRW_SST\", or\n--             (s.\"analysed_sst\" - 273.15) to convert Kelvin to Celsius)\n--   {{slab}}  the registered griddap file (parquet) or view\n--   {{mask}}  the mask table: latitude, longitude, weight (0,1]\n-- the join is an exact equality on ROUND(x, 3): the ERDDAP axis is float32 in the parquet and float64\n-- in the JS mask, so 21.375 arrives as 21.374999... on one side; rounding to the grid's 3 decimals\n-- (0.05 spacing) makes the two match without a tolerance join.\nSELECT\n  -- utc day; via epoch_ms because duckdb-wasm ships without icu, so TIMESTAMPTZ::DATE is unimplemented there\n  make_timestamp(epoch_ms(s.\"time\") * 1000)::DATE   AS date,\n  count({{expr}})                                  AS n,\n  avg({{expr}})                                    AS mean,\n  sum({{expr}} * m.weight) / sum(m.weight)         AS mean_wt,\n  stddev_samp({{expr}})                            AS sd,\n  min({{expr}})                                    AS min,\n  max({{expr}})                                    AS max,\n  quantile_cont({{expr}}, 0.10)                    AS p10,\n  quantile_cont({{expr}}, 0.90)                    AS p90,\n  sum(m.weight)                                     AS weight_sum\nFROM {{slab}} s\nJOIN {{mask}} m\n  ON  ROUND(s.latitude::DOUBLE,  3) = ROUND(m.latitude::DOUBLE,  3)\n  AND ROUND(s.longitude::DOUBLE, 3) = ROUND(m.longitude::DOUBLE, 3)\nWHERE {{expr}} IS NOT NULL\nGROUP BY 1\nORDER BY 1\n",
  stats_tabledap: "-- monthly key statistics for one place from an ERDDAP **tabledap** slab (point samples).\n--   {{expr}}  the value expression over the slab alias `s` (e.g. s.\"measurement_value\")\n--   {{slab}}  the registered tabledap file (parquet) or view\n--   {{mask}}  the station table: latitude, longitude (weight is 1 — a point is in or out)\n-- tabledap points are sparse and irregular, so the roll-up is by **month**, not by day: a CalCOFI\n-- quarterly cruise gives a handful of days a year, and a daily grouping would be mostly empty.\n-- `n_casts` counts the distinct sampling events (time x position) behind the n measurements, since\n-- one cast contributes many depths.\n-- the join is an exact equality on ROUND(x, 5): the station positions come back out of DuckDB, go\n-- through the JS point-in-polygon mask and come back in, so five decimals (~1 m) is exact here.\nWITH pts AS (\n  SELECT\n    -- utc, via epoch_ms because duckdb-wasm ships without icu: TIMESTAMPTZ::DATE is unimplemented there\n    make_timestamp(epoch_ms(s.\"time\") * 1000) AS ts,\n    s.longitude::DOUBLE                       AS longitude,\n    s.latitude::DOUBLE                        AS latitude,\n    {{expr}}                                  AS value\n  FROM {{slab}} s\n  JOIN {{mask}} m\n    ON  ROUND(s.latitude::DOUBLE,  5) = ROUND(m.latitude::DOUBLE,  5)\n    AND ROUND(s.longitude::DOUBLE, 5) = ROUND(m.longitude::DOUBLE, 5)\n  WHERE {{expr}} IS NOT NULL\n)\nSELECT\n  date_trunc('month', ts)::DATE                  AS date,\n  count(value)                                   AS n,\n  count(DISTINCT (ts, longitude, latitude))      AS n_casts,\n  avg(value)                                     AS mean,\n  stddev_samp(value)                             AS sd,\n  min(value)                                     AS min,\n  max(value)                                     AS max,\n  quantile_cont(value, 0.10)                     AS p10,\n  quantile_cont(value, 0.90)                     AS p90\nFROM pts\nGROUP BY 1\nORDER BY 1\n",
}
